{
  "criteria": [
    {
      "kind": "exclusion",
      "text": "Participant's tumor has any additional known primary driver alterations other than RET, such as targetable mutations of EGFR, ALK, ROS1, MET, and BRAF.",
      "quote": "Participant’s tumor has any additional known primary driver alterations other than RET, such as targetable mutations of EGFR, ALK, ROS1, MET, and BRAF."
    },
    {
      "kind": "exclusion",
      "text": "Participant previously received treatment with a selective RET inhibitor.",
      "quote": "Participant previously received treatment with a selective RET inhibitor."
    },
    {
      "kind": "exclusion",
      "text": "Participant received radiotherapy or radiosurgery to any site within 14 days before randomization or more than 30 Gy of radiotherapy to the lung in the 6 months before randomization.",
      "quote": "Participant received radiotherapy or radiosurgery to any site within 14 days before randomization or more than 30 Gy of radiotherapy to the lung in the 6 months before randomization."
    },
    {
      "kind": "exclusion",
      "text": "Participants with a history of pneumonitis of non-infectious etiology within the last 12 months.",
      "quote": "Participants with a history of pneumonitis of non-infectious etiology within the last 12 months."
    },
    {
      "kind": "exclusion",
      "text": "Participants with autoimmune disease that requires systemic therapy (excluding thyroid, vitiligo).",
      "quote": "Participants with autoimmune disease that requires systemic therapy (excluding thyroid, vitiligo)."
    },
    {
      "kind": "exclusion",
      "text": "Participants with autoimmune disease within 2 years of study enrollment are not eligible for the pembrolizumab-containing regimen.",
      "quote": "Participants with autoimmune disease within 2 years of study enrollment are not eligible for the pembrolizumab-containing regimen."
    },
    {
      "kind": "exclusion",
      "text": "Participants with a medical condition that requires immunosuppression.",
      "quote": "Participants with a medical condition that requires immunosuppression."
    },
    {
      "kind": "exclusion",
      "text": "Participant has either CNS metastases or a primary CNS tumor that is associated with progressive neurological symptoms or requires increasing doses of corticosteroids to control the CNS disease.",
      "quote": "Participant has either CNS metastases or a primary CNS tumor that is associated with progressive neurological symptoms or requires increasing doses of corticosteroids to control the CNS disease."
    },
    {
      "kind": "exclusion",
      "text": "Participant has significant cardiovascular disease, as evidenced by any of the following conditions: QTcF >480 ms, history of prolonged QT syndrome or torsades de pointes, familial history of prolonged QT syndrome, clinically significant uncontrolled cardiovascular disease including Grade III or IV congestive heart failure, myocardial infarction or unstable angina within previous 6 months, uncontrolled hypertension, or clinically significant uncontrolled arrhythmias including bradyarrhythmias that may cause QT prolongation.",
      "quote": "Participant has significant cardiovascular disease, as evidenced by any of the following conditions:",
      "thresholds": [
        {
          "test": "QTcF",
          "op": ">",
          "value": 480,
          "unit": "ms"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Participant requires treatment with a prohibited medication or herbal remedy (as specified in Section 6.8.3) that cannot be discontinued at least 2 weeks prior to the start of study drug administration.",
      "quote": "Participant requires treatment with a prohibited medication or herbal remedy (as specified in Section 6.8.3) that cannot be discontinued at least 2 weeks prior to the start of study drug administration."
    },
    {
      "kind": "exclusion",
      "text": "Participant received treatment with hematopoietic growth factor support within 14 days of the first dose of study drug.",
      "quote": "Participant received treatment with hematopoietic growth factor support within 14 days of the first dose of study drug."
    },
    {
      "kind": "exclusion",
      "text": "Participant has had a major surgical procedure within 14 days of the first dose of study drug or is planned to have such procedure during the study period.",
      "quote": "Participant has had a major surgical procedure within 14 days of the first dose of study drug or is planned to have such procedure during the study period."
    },
    {
      "kind": "exclusion",
      "text": "Participant has had a history of another primary malignancy that has been diagnosed or required therapy within the past 3 years prior to randomization.",
      "quote": "Participant has had a history of another primary malignancy that has been diagnosed or required therapy within the past 3 years prior to randomization."
    },
    {
      "kind": "exclusion",
      "text": "Participant has any of the following within 14 days prior to the first dose of study drug: Platelet count <75×10^9/L, ANC <1.0×10^9/L, Hemoglobin <9.0 g/dL, AST or ALT >3×ULN if no hepatic metastases, >5×ULN if hepatic metastases present, Total bilirubin >1.5×ULN, >3×ULN in presence of Gilbert disease, Estimated or measured creatinine clearance <45 mL/min, Total serum phosphorous >5.5 mg/dL.",
      "quote": "Participant has any of the following within 14 days prior to the first dose of study drug:",
      "thresholds": [
        {
          "test": "Platelet count",
          "op": "<",
          "value": 75,
          "unit": "10^9/L"
        },
        {
          "test": "ANC",
          "op": "<",
          "value": 1.0,
          "unit": "10^9/L"
        },
        {
          "test": "Hemoglobin",
          "op": "<",
          "value": 9.0,
          "unit": "g/dL"
        },
        {
          "test": "AST",
          "op": ">",
          "value": 3,
          "unit": "x ULN"
        },
        {
          "test": "ALT",
          "op": ">",
          "value": 3,
          "unit": "x ULN"
        },
        {
          "test": "Total bilirubin",
          "op": ">",
          "value": 1.5,
          "unit": "x ULN"
        },
        {
          "test": "Creatinine clearance",
          "op": "<",
          "value": 45,
          "unit": "mL/min"
        },
        {
          "test": "Total serum phosphorous",
          "op": ">",
          "value": 5.5,
          "unit": "mg/dL"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Participant has a known hypersensitivity to cisplatin, carboplatin, pemetrexed, or pembrolizumab (for participants with NSCLC of non-squamous histology only), or carboplatin, gemcitabine, pembrolizumab, paclitaxel, or nab-paclitaxel (for participants with NSCLC of squamous histology only).",
      "quote": "Participant has a known hypersensitivity to cisplatin, carboplatin, pemetrexed, or pembrolizumab (for participants with NSCLC of non-squamous histology only), or carboplatin, gemcitabine, pembrolizumab, paclitaxel, or nab-paclitaxel (for participants with NSCLC of squamous histology only)."
    },
    {
      "kind": "exclusion",
      "text": "Participant with a serious infection requiring systemic antibiotics within 7 days prior to initiation of study treatment, or any active infection that, in the opinion of the investigator, could impact patient's safety.",
      "quote": "Participant with a serious infection requiring systemic antibiotics within 7 days prior to initiation of study treatment, or any active infection that, in the opinion of the investigator, could impact patient's safety."
    },
    {
      "kind": "exclusion",
      "text": "Participant has an active, uncontrolled infection (viral, bacterial, or fungal).",
      "quote": "Participant has an active, uncontrolled infection (viral, bacterial, or fungal)."
    },
    {
      "kind": "exclusion",
      "text": "Participant has positive hepatitis C virus (HCV) antibody test at screening.",
      "quote": "Participant has positive hepatitis C virus (HCV) antibody test at screening."
    },
    {
      "kind": "exclusion",
      "text": "Participant has positive hepatitis B surface antigen (HBsAg) test at screening.",
      "quote": "Participant has positive hepatitis B surface antigen (HBsAg) test at screening."
    },
    {
      "kind": "exclusion",
      "text": "Participant is unwilling or unable to comply with scheduled visits, study drug administration plan (including the inability or unwillingness to swallow capsules), laboratory tests, or other study procedures and study restrictions.",
      "quote": "Participant is unwilling or unable to comply with scheduled visits, study drug administration plan (including the inability or unwillingness to swallow capsules), laboratory tests, or other study procedures and study restrictions."
    },
    {
      "kind": "exclusion",
      "text": "Participant is pregnant, as documented by a serum β-human chorionic gonadotropin (βhCG) pregnancy test consistent with pregnancy obtained within 7 days before the first dose of study drug.",
      "quote": "Participant is pregnant, as documented by a serum β-human chorionic gonadotropin (βhCG) pregnancy test consistent with pregnancy obtained within 7 days before the first dose of study drug."
    },
    {
      "kind": "exclusion",
      "text": "Participant is breastfeeding.",
      "quote": "Participant is breastfeeding."
    },
    {
      "kind": "exclusion",
      "text": "Participant with concurrent enrollment in another clinical study, unless it is an observational (noninterventional) clinical study, or during the follow-up period of an interventional study.",
      "quote": "Participant with concurrent enrollment in another clinical study, unless it is an observational (noninterventional) clinical study, or during the follow-up period of an interventional study"
    },
    {
      "kind": "exclusion",
      "text": "Participant has had a prior or has an ongoing clinically significant illness, medical condition, surgical history, physical finding, or laboratory abnormality that, in the investigator’s opinion, could affect the safety of the participant, alter the absorption, distribution, metabolism, or excretion of the study drug, or impair the assessment of study results.",
      "quote": "Participant has had a prior or has an ongoing clinically significant illness, medical condition, surgical history, physical finding, or laboratory abnormality that, in the investigator’s opinion, could affect the safety of the participant, alter the absorption, distribution, metabolism, or excretion of the study drug, or impair the assessment of study results."
    }
  ]
}
